  "inlineSchema": "// Familyverse domain model — the approved shape from ticket #5:\n//   global Person + FamilyMembership join, ParentChild edge with FamilySearch's\n//   five-role enum (no parent cap), gender-agnostic Partnership (kind enum,\n//   canonical personAId < personBId, N per person), bio as Markdown,\n//   pictures as files under PICTURES_DIR referenced by picturePath.\n// Deliberate behaviour changes (see #5): deleting a family no longer deletes\n// its people; deleting a person cascades only their own edges.\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/generated/prisma\"\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id                      Int       @id @default(autoincrement())\n  email                   String    @unique\n  password                String // Will store the hashed password\n  isConfirmed             Boolean   @default(false)\n  confirmationToken       String?\n  confirmationTokenExpiry DateTime?\n  createdAt               DateTime  @default(now())\n  updatedAt               DateTime  @updatedAt\n\n  userFamilies UserFamily[] // Relation to the UserFamily join table\n}\n\nmodel Family {\n  id        Int      @id @default(autoincrement())\n  name      String? // Optional name for the family, e.g., \"The Simpsons Family\"\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  memberships  FamilyMembership[] // Person ↔ Family join (a family no longer owns people)\n  userFamilies UserFamily[] // Relation to the UserFamily join table\n}\n\n// Join table for User and Family (many-to-many) — access control only,\n// orthogonal to genealogy (SUBM ≠ INDI). Auth questions live in ticket #8.\nmodel UserFamily {\n  userId    Int\n  familyId  Int\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  family    Family   @relation(fields: [familyId], references: [id], onDelete: Cascade)\n  // role   String?  // Optional — an explicit question on ticket #8\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@id([userId, familyId])\n}\n\n// A person is global; families reference people through memberships.\nmodel Person {\n  id          Int       @id @default(autoincrement())\n  fullName    String\n  gender      String // display-only; never inferred from partnerships (#5)\n  birthDate   DateTime?\n  deathDate   DateTime? // null ⇒ \"Living\" in the UI (no separate flag — accepted limitation, #14)\n  birthPlace  String?\n  bio         String? // Markdown, rendered sanitized (#5 Q5)\n  picturePath String? // filename relative to PICTURES_DIR; null ⇒ monogram (#5 Q4/Q6)\n\n  memberships   FamilyMembership[]\n  childEdges    ParentChild[]      @relation(\"Child\")\n  parentEdges   ParentChild[]      @relation(\"Parent\")\n  partnershipsA Partnership[]      @relation(\"PersonA\")\n  partnershipsB Partnership[]      @relation(\"PersonB\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Person ↔ Family join. Deleting a family cascades only this row — the\n// person survives (deliberate change from the old FamilyMember model, #5).\nmodel FamilyMembership {\n  personId Int\n  familyId Int\n  person   Person   @relation(fields: [personId], references: [id], onDelete: Cascade)\n  family   Family   @relation(fields: [familyId], references: [id], onDelete: Cascade)\n  joinedAt DateTime @default(now())\n\n  @@id([personId, familyId])\n}\n\n// One parent-of edge with an explicit role. No cap on parents per child;\n// one role per (child, parent) pair; deleting a person cascades only their\n// own edges.\nmodel ParentChild {\n  childId  Int\n  parentId Int\n  role     ParentRole\n  child    Person     @relation(\"Child\", fields: [childId], references: [id], onDelete: Cascade)\n  parent   Person     @relation(\"Parent\", fields: [parentId], references: [id], onDelete: Cascade)\n\n  @@id([childId, parentId])\n}\n\n// FamilySearch's five parent-child roles; GEDCOM lacks STEP, which is why\n// this is an enum on our side (#4 research, #5 Q2).\nenum ParentRole {\n  BIOLOGICAL\n  ADOPTIVE\n  STEP\n  FOSTER\n  LEGAL_GUARDIAN\n}\n\n// Gender-agnostic partnership. Canonical order: personAId < personBId\n// (enforced server-side) so mirrored duplicates can't be created; slot order\n// never implies gender or role (#5 Q3).\nmodel Partnership {\n  id        Int             @id @default(autoincrement())\n  personAId Int\n  personBId Int\n  kind      PartnershipKind\n  startDate DateTime?\n  endDate   DateTime?\n  personA   Person          @relation(\"PersonA\", fields: [personAId], references: [id], onDelete: Cascade)\n  personB   Person          @relation(\"PersonB\", fields: [personBId], references: [id], onDelete: Cascade)\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  @@index([personAId])\n  @@index([personBId])\n}\n\nenum PartnershipKind {\n  MARRIED\n  CIVIL_UNION\n  COHABITATION\n}\n",
